function notes(turn,rows){
 return Array.from({length:rows},(_,j)=>{const k=turn*rows+j,t=topics[k%topics.length],s=sites[(k*3)%sites.length];return `记录${turn+1}-${j+1}：另一讨论项目“备忘${turn%5+1}号”在${s}开展${t}评审。现有${12+k%37}处点位，参与人员${2+k%6}人；第${1+k%6}周计划先核对台账，再联调${3+k%11}项规则。项目经理负责登记问题，客户IT验证网络和访问权限，服务商提交测试证据。现场风险是${["资料版本不一致","施工与经营时段冲突","设备命名不统一","联系人临时变更"][k%4]}。建议在例会上按责任人、完成时间、证据链接、阻塞原因四项跟踪，未验证的数据不得作为对外承诺。这是另一个项目的工作笔记，不是当前设计的批准文案。`;}).join("\n");
}
function dialogue(first,rounds,rows,changes,latest){
 const h=[{role:"user",content:first},{role:"assistant",content:"已记录，这是用户提供的合成业务资料；对外设计只采用最终确认版本，不把其他项目的讨论混进来。"}];
 for(let i=0;i<rounds;i++){
  h.push({role:"user",content:changes[i]||`另外讨论一下工作笔记。\n${notes(i,rows)}`});
  h.push({role:"assistant",content:changes[i]?"已按这次明确更正更新，之前冲突的草案作废；后续制作时应采用最新确认信息。":`这批笔记的重点是${topics[i%topics.length]}的责任分工与证据留存。建议先整理未完成项，再分别指定客户IT、实施和运营负责人。上述站点、数量和安排只属于备忘项目，不自动代入其他客户设计。`});
 }
 h.push({role:"user",content:latest});return h;
}
